(() => {
  const root=document.querySelector('[data-navigator-bot]'); if(!root)return;
  const form=root.querySelector('form'), input=root.querySelector('[data-navigator-input]'), output=root.querySelector('[data-navigator-output]');
  const examples=root.querySelectorAll('[data-navigator-example]');
  const voiceButton=root.querySelector('[data-navigator-voice]'), voiceStatus=root.querySelector('[data-navigator-voice-status]');
  const intents=[
    {id:'emergency',terms:['911','emergency','immediate danger','not breathing','fire','overdose'],title:'Get urgent help now',text:'If someone may be in immediate danger, call 911. Franklin Navigator does not dispatch responders.',links:[['Call 911','tel:911'],['Open emergency starting points','/community-help-center/#urgent-help']]},
    {id:'crisis',terms:['suicide','988','mental health crisis','panic','crisis'],title:'Mental-health or emotional crisis',text:'Call or text 988 for crisis support. Use 911 when there is immediate danger.',links:[['Open Tennessee crisis help','https://www.tn.gov/behavioral-health/crisis.html'],['Community Help Center','/community-help-center/']]},
    {id:'move',terms:['moved','moving','new to franklin','just moved','utilities','new resident'],title:'New to Franklin',text:'Start with utilities, school routing, local government and other move-in tasks.',links:[['Start the moving checklist','/new-to-franklin/'],['Build a Get It Done plan','/get-it-done/#move']]},
    {id:'school',terms:['school','enroll','enrollment','kindergarten','student','school zone','bus route'],title:'School and enrollment help',text:'Franklin addresses can involve Franklin Special District or Williamson County Schools. Start by identifying the correct district and school-zone source.',links:[['School enrollment guide','/school-enrollment/'],['My Franklin family setup','/my-franklin/']]},
    {id:'transport',terms:['bus','transit','ride','transportation','no car','cannot drive','senior transportation','paratransit'],title:'Transportation and mobility',text:'Compare Franklin Transit, accessible transportation and other local starting points.',links:[['Transportation pathway','/local-pathways/transportation-mobility/'],['Franklin Transit schedules','https://franklintransit.org/franklin-transit-routes-schedules/']]},
    {id:'permit',terms:['permit','remodel','addition','contractor','building','fence','deck','zoning'],title:'Permit or home project',text:'Organize the project first, then use the correct City permit or planning source.',links:[['Plan the project','/permits-home/'],['Get It Done: permits','/get-it-done/#permit']]},
    {id:'property',terms:['property record','property tax','assessor','parcel','zoning','hoa','mortgage notice'],title:'Property, records and home documents',text:'Use the home/property tools to separate records, permits, zoning and document questions before contacting the responsible office.',links:[['Home and property help','/housing/'],['Home Rights & Notice Center','/home-rights-center/']]},
    {id:'housing',terms:['rent','renter','eviction','affordable housing','housing','landlord','workforce housing'],title:'Housing help',text:'Start with housing, renter/homeowner and affordability resources; legal questions remain separate from housing-program eligibility.',links:[['Housing and home help','/housing/'],['Community Help Center','/community-help-center/']]},
    {id:'food',terms:['food','snap','benefits','groceries','utility help','basic needs'],title:'Food, benefits and basic needs',text:'Use the local pathway to find food and benefit starting points without entering household details.',links:[['Food & Benefits pathway','/local-pathways/food-benefits/'],['Urgent/basic-needs help','/community-help-center/']]},
    {id:'senior',terms:['senior','elderly','aging','caregiver','mother','father','parent needs help','caregiving'],title:'Senior and caregiver support',text:'Organize transportation, aging, disability, veteran and caregiving needs around local starting points.',links:[['Senior & Caregiving pathway','/local-pathways/seniors-caregiving/'],['Senior/caregiver guide','/senior-caregiver/']]},
    {id:'health',terms:['doctor','health','medical','clinic','dentist','insurance','medication','care'],title:'Health and care',text:'Prepare questions, find appropriate care starting points and keep emergencies on the urgent-help route.',links:[['Health and care help','/health-help/'],['Find health listings','/directory/?q=health']]},
    {id:'legal',terms:['lawyer','attorney','court','legal','lawsuit','divorce','custody','ticket','warrant'],title:'Legal or court starting help',text:'Use general preparation and official-source navigation; Franklin Navigator does not provide legal advice or calculate deadlines.',links:[['Legal starting help','/legal-help/'],['Find legal-service listings','/directory/?q=legal']]},
    {id:'auto',terms:['car','vehicle','mechanic','crash','accident','recall','repair','tow'],title:'Vehicle help',text:'Start with safety, records, repair or buying/registration guidance, then find local options if needed.',links:[['Auto and vehicle help','/auto-vehicle-help/'],['Find auto listings','/directory/?q=auto']]},
    {id:'trash',terms:['trash','garbage','recycling','brush','bulk waste','yard waste','sanitation'],title:'Trash, recycling and sanitation',text:'Use City sanitation guidance for collection, recycling, brush and bulk-waste questions inside Franklin city limits.',links:[['Everyday help','/everyday-help/?q=trash'],['City sanitation source','https://www.franklintn.gov/government/departments-k-z/sanitation-and-environmental-services']]},
    {id:'event',terms:['event','weekend','tonight','music','festival','things to do','family activity','market'],title:'What is happening around Franklin?',text:'Start with Today in Franklin and Live Local, then confirm changing event details at the original source.',links:[['Today in Franklin','/today/'],['Live Local','/live-local/']]},
    {id:'civic',terms:['meeting','alderman','ward','vote','voting','public hearing','city council','boma','development near me'],title:'Civic and neighborhood information',text:'Find meetings, wards, development activity and ways to participate using official Franklin sources.',links:[['Civic & Neighborhood pathway','/local-pathways/civic-neighborhood/'],['Today in Franklin','/today/#civic']]},
    {id:'jobs',terms:['job','career','internship','work','hiring','resume'],title:'Jobs and career',text:'Build a Franklin-area job, training or career plan and connect to local employers and workforce resources.',links:[['Jobs & Career pathway','/local-pathways/jobs-career/'],['Jobs & internships','/jobs-internships/']]},
    {id:'childcare',terms:['child care','childcare','daycare','preschool','babysitter'],title:'Child care and family support',text:'Start with licensed child-care and family-support routes, then confirm availability and requirements directly.',links:[['Children & Family pathway','/local-pathways/children-family/'],['Get It Done: family support','/get-it-done/#children-family']]},
    {id:'utilities',terms:['electric','water bill','utility','utilities','power bill','sewer','internet'],title:'Utilities and household services',text:'Start with the responsible Franklin-area provider or basic-needs route, depending on whether you are setting up service or need help paying.',links:[['New to Franklin utilities','/new-to-franklin/'],['Food, benefits & basic needs','/get-it-done/#food-benefits']]},
    {id:'parks',terms:['park','playground','recreation','sports field','trail','pickleball'],title:'Parks and recreation',text:'Use Franklin Parks and community starting points for facilities, programs and recreation.',links:[['Community & parks','/community/'],['Franklin Parks','https://www.franklintn.gov/government/departments-k-z/parks']]},
    {id:'pets',terms:['pet','dog','cat','vet','veterinary','groomer','boarding'],title:'Pets and animal services',text:'Find animal-service starting points and compare local veterinary, boarding, grooming or pet-care options.',links:[['Pets & Animal Services pathway','/local-pathways/pets-animals/'],['Find pet-service listings','/directory/?q=pet']]},
    {id:'start-business',terms:['start business','open a business','business license','new business','opening a','startup'],title:'Start or license a Franklin business',text:'Work through licensing, zoning, permits and local business-support starting points in the right order.',links:[['Start & Run a Business pathway','/local-pathways/start-run-business/'],['Get It Done: business license','/get-it-done/#business-license']]},
    {id:'grow-business',terms:['more customers','grow my business','business growth','marketing','visibility','my business','customers','local seo'],title:'Grow a Franklin business',text:'Check your public presence, choose one goal and get a practical weekly or 90-day plan.',links:[['Business Growth Planner','/local-growth-engine/'],['Business Growth Guides','/navigator-growth-desk/'],['My business dashboard','/business-dashboard/']]}
  ];
  const serviceTerms=[['plumber','plumber'],['plumbing','plumber'],['electrician','electrician'],['hvac','hvac'],['air conditioning','hvac'],['roofer','roofing'],['roofing','roofing'],['landscaper','landscaping'],['lawn','landscaping'],['salon','salon'],['haircut','salon'],['restaurant','restaurant'],['accountant','accounting'],['bookkeeper','accounting'],['tax preparer','tax'],['realtor','real estate'],['real estate agent','real estate'],['insurance agent','insurance'],['tutor','tutoring'],['daycare','child care'],['dentist','dentist'],['doctor','doctor'],['vet','veterinary'],['veterinarian','veterinary'],['mechanic','auto repair'],['tow truck','towing'],['cleaner','cleaning'],['house cleaning','cleaning']];
  const normalize=s=>String(s||'').toLowerCase().replace(/[^a-z0-9\s'-]/g,' ').replace(/\s+/g,' ').trim();
  const score=(text,intent)=>intent.terms.reduce((sum,term)=>sum+(text.includes(term)?(term.includes(' ')?4:2):0),0);
  const render=(raw)=>{output.hidden=false;
    const text=normalize(raw); if(!text){output.innerHTML='<p>Tell me what you need in a few words. I will point you to the best Franklin starting place.</p>';return;}
    const ranked=intents.map(intent=>({intent,score:score(text,intent)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,3);
    if(!ranked.length){const service=serviceTerms.find(([term])=>text.includes(term));if(service){const query=encodeURIComponent(service[1]);output.innerHTML=`<h3>Find a local ${service[1]} option</h3><p>I can take you directly to Franklin-area listings. Compare the public facts and confirm current availability, price, credentials or fit directly with the provider.</p><div class="actions"><a class="button primary" href="/directory/?q=${query}">Search local listings</a><a class="button" href="/profile/">How local profiles work</a></div>`;return}output.innerHTML='<h3>Let’s narrow it down.</h3><p>I did not find a close match yet. Try the goal instead of the agency name—for example “I need help with rent,” “I need a permit,” “find a plumber,” or “I want more customers.”</p><div class="actions"><a class="button primary" href="/community-help-center/">Open the Help Center</a><a class="button" href="/directory/">Search local listings</a><a class="button" href="/get-it-done/">Browse Get It Done</a></div>';return;}
    output.replaceChildren();
    ranked.forEach(({intent},index)=>{const card=document.createElement('article');card.className='navigator-result';const h=document.createElement(index===0?'h3':'h4');h.textContent=intent.title;const p=document.createElement('p');p.textContent=intent.text;const actions=document.createElement('div');actions.className='actions';intent.links.forEach(([label,href],i)=>{const a=document.createElement('a');a.className=`button${index===0&&i===0?' primary':''}`;a.href=href;a.textContent=label;if(href.startsWith('http')){a.target='_blank';a.rel='noopener'}actions.append(a)});card.append(h,p,actions);output.append(card)});
  };

  const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(voiceButton&&SpeechRecognition){
    voiceButton.hidden=false;
    let listening=false;
    const recognition=new SpeechRecognition();
    recognition.lang='en-US';recognition.interimResults=false;recognition.continuous=false;recognition.maxAlternatives=1;
    const setVoiceStatus=message=>{if(voiceStatus)voiceStatus.textContent=message};
    recognition.addEventListener('start',()=>{listening=true;voiceButton.textContent='Listening…';voiceButton.setAttribute('aria-pressed','true');setVoiceStatus('Listening. Speak a short Franklin question or goal.')});
    recognition.addEventListener('result',event=>{const transcript=String(event.results?.[0]?.[0]?.transcript||'').trim();if(transcript){input.value=transcript;render(transcript);output.focus()}setVoiceStatus('Voice input captured. Review the words before using any outside link.')});
    recognition.addEventListener('error',event=>{setVoiceStatus(event.error==='not-allowed'?'Voice permission was not granted. You can keep typing instead.':'Voice input did not finish. You can try again or keep typing.')});
    recognition.addEventListener('end',()=>{listening=false;voiceButton.textContent='Speak';voiceButton.setAttribute('aria-pressed','false')});
    voiceButton.addEventListener('click',()=>{if(listening){recognition.stop();return}try{recognition.start()}catch{setVoiceStatus('Voice input is already starting.')}});
  }

  form.addEventListener('submit',e=>{e.preventDefault();render(input.value);output.focus()});
  examples.forEach(button=>button.addEventListener('click',()=>{input.value=button.dataset.navigatorExample||button.textContent;render(input.value)}));
})();
